    for char in line:
        stack.append(char)
        for _ in range(k):
            try:
                prefix = ''.join(stack[:k])
                suffix = ''.join(stack[-1:])
                minimum = stack.remove(min(prefix, suffix, key=stack.count))
                if minimum == prefix:
                    stack.pop()
                else:
