from math import gcd

def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def prime_factorization(num):
    prime_factors_dict = {}
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            prime_factors_dict[i] = prime_factors_dict.get(i, 0) + 1
            while num % i == 0:
                num //= i
                prime_factors_dict[i] += 1
    if num > 1:
        prime_factors_dict[num] = 1
    return prime_factors_dict

def find_min_operations(a, b):
    factor_a = prime_factorization(a)
    factor_b = prime_factorization(b)

    a_divisors = 1
    b_divisors = 1
    for prime, count in factor_a.items():
        a_divisors *= (sum(range(1, count + 1)))
    for prime, count in factor_b.items():
        b_divisors *= (sum(range(1, count + 1)))

    operations_needed = abs(a_divisors - b_divisors)
    return operations_needed

