        # Replace chars[i...j-1] with last_ending_char and chars[j...]
        while i < j:
            chars[i] = last_ending_char
            i += 1

        # If the last char is not same, just return
        if chars[j-2] != last_ending_char:
            return ''

        # Replace chars[j] to 2*last_ending_char - 1
        chars[j] = 2*last_ending_char - 1

    for i in range(len(chars)):
