    def is_valid_saek(self, saek):
        if saek.startswith('(') and saek.endswith(')'):
            stack = []
            for i in range(len(saek)):
                char = saek[i]
                if char == '(':
                    stack.append(char)
                elif char == ')':
                    temp = 0
                    while stack and stack[-1] != '(':
                        temp = (10 * temp) + int(stack.pop())
                    if len(stack) > 0:
                        stack.pop()  # Remove '(' from the stack
                        if temp != 0 and (i == 0 or saek[i-1] != '*') and saek[i-1] != '+':
                            return False
                    else:
                        return False
            return len(stack) == 0 and saek.endswith('*') or saek.endswith('+')
        return False

    def evaluate_saek(self, saek):
        stack = []
        for i in range(len(saek)):
            char = saek[i]
            if char.isdigit():
                temp = 0
                while i < len(saek) and saek[i].isdigit():
                    temp = (10 * temp) + int(saek[i])
                    i += 1
                if len(stack) > 0:
                    temp *= int(stack.pop())
                stack.append(str(temp))
            elif char == '*':
                temp = int(stack.pop())
                while len(stack) > 0 and stack[-1] != ')':
                    temp *= int(stack.pop())
                    stack.pop()
                stack.append(str(temp))
            elif char == '+':
                x = int(stack.pop())
                if len(stack) > 0:
                    x += int(stack.pop())
                stack.append(str(x))
            elif len(stack) > 0 and stack[-1] != '(':
                stack.append(char)
        return stack[-1]

