            saek = self.evaluate(saek)
            if saek.startswith('(') and saek.endswith(')'):
                saek = saek.replace(')', '').replace('(', '')
            result.append(self.evaluate_saek(saek))
        return result

    def get_saek_bit(self, expression, index):
        stack = []
        current_saek = ''
        while index < len(expression):
            char = expression[index]
            if char == '.':
                stack.append(current_saek)
                current_saek = ''
            elif char.isalpha():
                current_saek += char
            elif char.isdigit():
                current_saek += char
                if current_saek.startswith('10'):
                    index += 4
                    return self.process_bits(expression, index)
                if len(stack) == 0:
                    return expression[index:]
                stack.append(current_saek)
                current_saek = ''
            index += 1
        if len(stack) > 0:
            return ''.join(stack)
        return None

    def get(self, saek, index):
        if index < len(saek) and saek[index].isdigit():
            return saek
        else:
            index += 1
            if index < len(saek) and saek[index].isdigit():
                return saek[0:index[0]]
            else:
