def find_final_value(tasks, k):
    graph = [[] for _ in range((2001))]

    # Construct the graph
    for idx, value in enumerate(tasks):
        root = value // k
        graph[root].append(idx)

    # Run DFS from root=1 and check for cycle
    visited = [-1] * 2001
    visited[1] = 0
    stack = [0]

    while stack:
        node = stack.pop(0)
        for child in graph[node]:
            if visited[child] == -1:
                visited[child] = visited[node] + 1
                stack.append(child)
            elif visited[node] < visited[child]:
                cycle = True
                break

        if cycle:
            return 0

    # Check if cycle is closed, we are done
    if cycle(False, 0, 0, False, None, k, k, 1, visited):
        return 1, visited[0]
    return 0, -1

