def count_char_positions(char, string):
    """Count occurrences of a character in the string, considering the replacement pattern."""
    return string.count(char) + string[::-1].count(char)

def lexicographically_minimal_string(s, k):
    """Generate the lexicographically minimal string from the given conditions."""
    positions = s.split(" ")
    for char in s[::-1]:
        if count_char_positions(char, "".join(positions)) >= k:
            positions.insert(0, positions.pop())
    return "".join(positions)

