            return False
        if r < 1 or c < 1:
            return False
        if r == n and c == m:
            return True
        # Try to decrease the value and find possible moves
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
