from collections import Counter

def can_obtain(residues, n, m):
    mod_dict = Counter()
    for num in residues:
        mod_dict[num] += 1
    for i in range(n):
        mod_dict[i%m] += 1
    return all(count % m == 0 for count in mod_dict.values())

def find_invaluable_residues(residues, n, mod):
    mod_dict = Counter()
    for num in residues:
        mod_dict[num] += 1
    for i in range(n):
        mod_dict[i%mod] += 1
    res = list(mod_dict)
    return len([x for x in res if not can_obtain([y for y in mod_dict.keys() if x != y], n, mod)])

n, m = map(int, input().split())
residues = list(map(int, input().split()))
print(find_invaluable_residues(residues, n, m))
