import math

def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def count_divisors(n):
    factors = prime_factors(n)
    for prime in factors:
        count = 0
        temp = n
        while temp % prime == 0:
            temp //= prime
            count += 1
        for j in range(1, count + 1):
            n = n ** (prime - 1) * math.comb(count, j)
    return count

def min_operations(a, b):
    if a % math.gcd(a, b) == 0 and b % math.gcd(a, b) == 0:
        return 0
    else:
        operations = 0
        while math.gcd(a, b) == ex_gcd(a, b):
            a, b = b, a % b
            operations += 1
        return operations

def ex_gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

t = int(input().strip())
for _ in range(t):
    a, b = map(int, input().strip().split())
    print(min_operations(a, b))
