from functools import cache

def lexicographically_smallest(s, k):
    n = len(s)
    dp = {(0, 0): ""}  # Initialize DP table with string "", index 0, and empty list for substrings
    for i in range(n):
        new_dp = {}
        for j in range(k + 1):
            for d in dp.get((i, j), ()):
                for l in range(i + 1, j + 1):
                    new_dp[(l, k - j)] = new_dp.get((l, k - j), "") + s[l - 1]
                    if l > i + 1:  # Append the reversed substring
                        new_dp[(l, k)] = new_dp.get((l, k), "") + s[j + 1 - l]
                        if l > i + 1:
                            new_dp[(i, j)] = min(dp.get((i, j), ""), new_dp[(l, k)])
        dp = new_dp

    return min([s[i] for i in range(n) if len(dp.get((i, k - len(dp) + 1))) == 0], default='')
